#!/usr/bin/env bash
#
# Device-build signing wizard for LoopMobile (임채승의 iPhone 15).
# Generated by the /wizard skill for task mobile-resilience.
#
# xcodebuild CLI cannot finish a device build right now:
#   - team GFD8JFK42C: its "Apple Development" cert is REVOKED
#     (security verify-cert → CSSMERR_TP_CERT_REVOKED)
#   - no valid Xcode account session for VMG62K6D6T or S5W794Z5NN
#     ("No Account for Team …")
# Stages 1–3 are human-only (Xcode GUI). Stages 4–5 the wizard runs itself:
# Release build → devicectl install → launch on the paired iPhone 15.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit it.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    else command -v open        >/dev/null 2>&1 && open "$url"
    fi
  } >/dev/null 2>&1 || warn "couldn't open it; visit manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
IOS_DIR="$REPO/apps/loop-mobile/ios"
DERIVED="$IOS_DIR/build"
DEVICE_UDID="00008120-000A0DEA02D1A01E"          # 임채승의 iPhone (xcodebuild destination)
DEVICE_DCTLD="B31B68D5-3A83-56EF-8F0D-D7A24E01F311" # devicectl identifier
BUNDLE_ID="org.reactjs.native.example.LoopMobile"

TOTAL_STAGES=5

banner "LoopMobile 실기기 서명 · 빌드 · 설치"

stage "1/5 · Xcode 계정 세션 복구 (사람만 가능)"
say "xcodebuild가 'No Account for Team' 오류를 내는 상태입니다 —"
say "Xcode에 저장된 계정 자격증명 세션이 만료되었거나 비어 있습니다."
open_url "xcode://"
step "Xcode 실행 → Settings… (⌘,) → Accounts 탭."
step "VMG62K6D6T (SEVEN PICTURES) 또는 본인 개인 팀(S5W794Z5NN) 계정 선택."
step "자격증명이 만료되었다면 다시 로그인하거나 Apple ID로 재인증하세요."
step "계정이 아예 없다면 '＋' → Apple ID로 추가하세요."
pause "계정이 Accounts 목록에서 경고 없이 보이면 Enter를 누르세요."

stage "2/5 · 취소된 인증서 교체 (사람만 가능)"
say "현재 GFD8JFK42C 팀의 'Apple Development: 채승 임' 인증서가 취소되었습니다"
say "(security verify-cert → CSSMERR_TP_CERT_REVOKED). 교체가 필요합니다."
step "Settings… → Accounts → 팀 선택 → 'Manage Certificates…'."
step "취소된 'Apple Development' 인증서(채승 임, 2025-12-26 만료 예정)를 − 버튼으로 삭제."
step "＋ 버튼 → 'Apple Development'로 새 인증서를 발급받으세요."
note "  개인 팀(S5W794Z5NN, cotmd6203@naver.com)을 쓸 거라면 그 팀의 인증서가"
note "  유효한지(취소 아님)만 확인하면 됩니다 — 이미 유효 상태로 보입니다."
pause "새(또는 유효한) 인증서가 목록에 있으면 Enter를 누르세요."

stage "3/5 · 서명 팀 선택"
say "LoopMobile 타깃 서명에 사용할 팀 ID를 정합니다."
step "LoopMobile 프로젝트 → LoopMobile 타깃 → Signing & Capabilities."
step "'Automatically manage signing' 체크 → Team에서 팀 선택 → 오류 소멸 확인."
say ""
say "  1) VMG62K6D6T  — SEVEN PICTURES (프로비저닝 프로파일 이미 존재, 권장)"
say "  2) S5W794Z5NN  — 개인 팀 (cotmd6203@naver.com, 첫 설치면 새 프로파일 생성)"
ask TEAM_ID "팀 ID 입력 [Enter=VMG62K6D6T]:"
TEAM_ID=${TEAM_ID:-VMG62K6D6T}
write_env LOOP_DEVICE_TEAM "$TEAM_ID"

stage "4/5 · Release 빌드 (자동)"
say "팀 $TEAM_ID 로 Release(iphoneos) 빌드를 시작합니다. 몇 분 걸립니다."
if confirm "지금 빌드할까요?"; then
  ( cd "$IOS_DIR" && xcodebuild \
      -workspace LoopMobile.xcworkspace \
      -scheme LoopMobile \
      -configuration Release \
      -destination "platform=iOS,id=$DEVICE_UDID" \
      "DEVELOPMENT_TEAM=$TEAM_ID" \
      CODE_SIGN_STYLE=Automatic \
      -allowProvisioningUpdates \
      -derivedDataPath "$DERIVED" build ) || {
    warn "빌드 실패 — 위의 마지막 error: 줄을 확인하세요. (보통 서명 단계 미완료)"
    exit 1
  }
  say "빌드 성공: $DERIVED/Build/Products/Release-iphoneos/LoopMobile.app"
else
  SKIPPED+=("빌드 (나중에 수동: stage 4의 xcodebuild 명령)")
fi

stage "5/5 · 설치 + 실행 (자동)"
APP="$DERIVED/Build/Products/Release-iphoneos/LoopMobile.app"
if confirm "iPhone 15에 설치하고 실행할까요?"; then
  xcrun devicectl device install app --device "$DEVICE_DCTLD" "$APP"
  xcrun devicectl device process launch --device "$DEVICE_DCTLD" "$BUNDLE_ID" \
    && say "앱이 기기에서 실행되었습니다 — 아래 체크리스트로 복원력을 확인하세요."
else
  SKIPPED+=("설치 (나중에 수동: xcrun devicectl device install app --device $DEVICE_DCTLD $APP)")
fi

finish
